	function get_custom_transactions_total($pid, $date)
	{
		$this->db->select('tbl_master_transaction.id,tbl_master_transaction.t_date,tbl_shift.id as shiftid,tbl_ledger.id as ledgerid,tbl_ledger.ledger_name,tbl_trans_add.number as trnno,tbl_trans_add.Amount as trn_amt');
		$this->db->select('tbl_trans_cross.ander,tbl_trans_cross.bahar,tbl_trans_cross.cross_count,tbl_trans_cross.amount as trncrs_amt');
		$this->db->select('tbl_random_f4.number,tbl_random_f4.amount,tbl_random_f4.total_amount as trnf4_tamt');
		$this->db->select('tbl_trans_fromto.fromto_from,tbl_trans_fromto.fromto_to,tbl_trans_fromto.fromto_amount,tbl_trans_fromto.all_commission');
		$this->db->select('tbl_random_f8.dara_f8,tbl_random_f8.dara_amount_f8,tbl_random_f8.akhar_bahar_f8,tbl_random_f8.amount_akahr_bahar_f8,tbl_random_f8.akahr_andar_f8,tbl_random_f8.amount_akahr_andar_f8,tbl_random_f8.total_amount ');
		$this->db->from('tbl_master_transaction');
		$this->db->join('tbl_trans_add', 'tbl_trans_add.master_id = tbl_master_transaction.id', 'FULL OUTER JOIN');
		$this->db->join('tbl_random_f4', 'tbl_random_f4.trns_id = tbl_master_transaction.id', 'FULL OUTER JOIN');
		$this->db->join('tbl_random_f8', 'tbl_random_f8.master_id = tbl_master_transaction.id', 'FULL OUTER JOIN');

		$this->db->join('tbl_trans_cross', 'tbl_trans_cross.master_id = tbl_master_transaction.id', 'FULL OUTER JOIN');
		$this->db->join('tbl_ledger', 'tbl_ledger.id = tbl_master_transaction.party_id', 'FULL OUTER JOIN');
		$this->db->join('tbl_shift', 'tbl_shift.id = tbl_master_transaction.shift_id', 'FULL OUTER JOIN');
		$this->db->join('tbl_trans_fromto', 'tbl_trans_fromto.master_id = tbl_master_transaction.id', 'FULL OUTER JOIN');
		$this->db->where('tbl_master_transaction.party_id', $pid);
		$this->db->where('tbl_master_transaction.t_date', $date);
		$this->db->order_by("tbl_master_transaction.id", "desc");
		//$this->db->limit('10', '0');		
		//$this->db->order_by('id', 'desc');
		if (isset($params) && !empty($params)) {
			$this->db->limit($params['limit'], $params['offset']);
		}
		$query = $this->db->get();
		//echo $this->db->last_query(); die;
		return $query->result_array();
	}

