	function add_Tb_Date_total_akhar_numbertempedit($key, $id, $party_id, $date, $data)
	{ //echo $id;
		$gdata = $this->getexistingdata($id);
		//echo '<pre>'; print_r($gdata); print_r($data); echo '</pre>'; die;
		//$gdata['Open_Number_amount'] =0;
		//$gdata['Akhar_Number_amount'] =0;
		//if($key){
		if ($key == '1') {
			$param['Open_Number_amount'] = $data['Open_Number_amount'];
			$param['Akhar_Number_amount'] = $data['Akhar_Number_amount'];
			$param['Total_amount'] = $data['Total_amount'];
		} else {
			$param['Open_Number_amount'] = $gdata['Open_Number_amount'] + $data['Open_Number_amount'];
			$param['Akhar_Number_amount'] = $gdata['Akhar_Number_amount'] + $data['Akhar_Number_amount'];
			$param['Total_amount'] = $data['Total_amount'] + $gdata['Total_amount'];
		}

		$param['Total_Number_amount'] = $gdata['Total_Number_amount'];
		$param['Total_Akhar_amount'] = $gdata['Total_Akhar_amount'];


		// get_transaction_result_total
		//$tdata= $this->tnumberdetails($shift_id,$data[$i]['party_id'],$date);
		$thridparty = $this->thirdpartydetails($party_id);
		//echo '<pre>';print_r($data);
		//echo '<pre>';print_r($tdata);
		//echo '<pre>';print_r($thridparty); echo '</pre>';die;
		$param['DARATotalAmt'] = $gdata['DaraRate'] * $param['Open_Number_amount'];
		$param['AmountCom'] = ($param['Total_Number_amount'] * $gdata['Commision']) / 100;
		$param['AkarAmount'] = ((isset($param['Akhar_Number_amount'])) ? $param['Akhar_Number_amount'] : '0') * $gdata['AkarRate'];
		$param['Akharcom'] = (((isset($param['Total_Akhar_amount'])) ? $param['Total_Akhar_amount'] : '0') * $gdata['Commission']) / 100;
		$param['AkarNumber_AndBothComisionTotal'] = $param['DARATotalAmt'] + $param['AmountCom'] + $param['AkarAmount'] + $param['Akharcom'];
		$param['ProfitAmount'] = ($param['Total_amount'] - $param['AkarNumber_AndBothComisionTotal']);
		//$param['RebateAmount'] = ($param['ProfitAmount']*$thridparty['rebate'])/100;
		$param['RebateAmount'] = 0;
		$param['ProfiteAfterRebate'] = $param['ProfitAmount'] - $param['RebateAmount'];
		$param['TP_person'] = (isset($thridparty['tp_party_id'])) ? $thridparty['tp_party_id'] : '0';
		if ($param['TP_person'] != "") {
			$param['TP_perc'] = (isset($thridparty['tppercentage'])) ? $thridparty['tppercentage'] : '0';
			$param['TP_Amount'] = ($param['ProfiteAfterRebate'] * $param['TP_perc']) / 100;
		} else {
