	function ledger_final_same_date_exist($party_id, $date)
	{
		return $this->db->order_by('id', 'desc')->limit(1, 0)->get_where('final_ledger', array('PartyId' => $party_id, 'Date' => date('Y-m-d', strtotime($date))))->row_array();
