	}
	function view_transaction_filter($data)
	{ //echo '<pre>'; print_r($data);die;
		//$data['created_by'] = $this->session->userdata['id'];
		$this->db->select('tbl_master_transaction.id,tbl_staff.staff_name,tbl_shift.open_date,tbl_shift.super_admin,tbl_shift.data_entry_operator,tbl_master_transaction.t_date,tbl_master_transaction.total_number_amount,tbl_master_transaction.created_date, tbl_master_transaction.party_id,tbl_shift.shift_name as shift_name,tbl_shift.id as shift_id,tbl_ledger.ledger_name,tbl_trans_numbers.createddate,tbl_trans_numbers.modifieddate,tbl_trans_numbers.trnno,tbl_trans_numbers.trn_amt');
		$this->db->from('tbl_master_transaction');

		// Aggregate number rows first so each master transaction is returned once.
		$this->db->join(
			'(SELECT master_id,
				GROUP_CONCAT(number ORDER BY id) AS trnno,
				GROUP_CONCAT(amount ORDER BY id) AS trn_amt,
				MAX(created_date) AS createddate,
				MAX(modified_date) AS modifieddate
			 FROM tbl_trans_numbers
			 GROUP BY master_id) AS tbl_trans_numbers',
			'tbl_trans_numbers.master_id = tbl_master_transaction.id',
			'LEFT',
			FALSE
		);
		$this->db->join('tbl_ledger', 'tbl_ledger.id = tbl_master_transaction.party_id', 'FULL OUTER JOIN');
		$this->db->join('tbl_agent', 'tbl_ledger.agent_id = tbl_agent.id', 'LEFT');
		$this->db->join('tbl_staff', 'tbl_staff.id = tbl_master_transaction.created_by', 'LEFT');
		if ($this->session->userdata['role'] == 'Master') {
			//echo '<pre>'; print_r($data); echo '</pre>'; die;
			// foreach($data['created_by'] as $val){
			// 	$this->db->or_where('tbl_master_transaction.created_by',$val);
			// 	$this->db->where('tbl_staff.updated_by',$this->session->userdata['id']);
			// 	$this->db->where('tbl_staff.id',$val);
			// }
			$this->db->join('user_shift_timings', 'user_shift_timings.id = tbl_master_transaction.shift_id', 'FULL OUTER JOIN');
			$this->db->join('tbl_shift', 'tbl_shift.id = user_shift_timings.shift_id', 'FULL OUTER JOIN');
			$this->db->where('tbl_master_transaction.master_id', $this->session->userdata['id']);
		} else if ($this->session->userdata['role'] == 'Super Admin') {
			$this->db->join('user_shift_timings', 'user_shift_timings.id = tbl_master_transaction.shift_id', 'FULL OUTER JOIN');
			$this->db->join('tbl_shift', 'tbl_shift.id = user_shift_timings.shift_id', 'FULL OUTER JOIN');
			$this->db->or_where('tbl_ledger.is_master', '1');
			//$this->db->group_by("tbl_master_transaction.party_id");
			$this->db->where('(tbl_master_transaction.party_id, tbl_master_transaction.id) IN (SELECT tbl_master_transaction.party_id, MAX(tbl_master_transaction.id) FROM tbl_master_transaction GROUP BY tbl_master_transaction.party_id,tbl_master_transaction.shift_id)', NULL, FALSE);
			//$this->db->limit(1); 
		} else {
			//$this->db->join('tbl_shift', 'tbl_shift.id = tbl_master_transaction.shift_id','FULL OUTER JOIN');
			$this->db->join('user_shift_timings', 'user_shift_timings.id = tbl_master_transaction.shift_id', 'FULL OUTER JOIN');
			$this->db->join('tbl_shift', 'tbl_shift.id = user_shift_timings.shift_id', 'FULL OUTER JOIN');
			$data['created_by'] = (!empty($data['created_by'])) ? $data['created_by'] : $this->session->userdata['id'];
			$this->db->where('tbl_master_transaction.created_by', $data['created_by']);
		}




		if (isset($data['shift_name']) && !empty($data['shift_name'])) {
			$this->db->where('tbl_shift.id', $data['shift_name']);
		}
		if (isset($data['search_party']) && !empty($data['search_party'])) {
			$this->db->where('tbl_ledger.id', $data['search_party']);
		}
		/*if(isset($data['fromdate'])&& !empty($data['fromdate'])){$this->db->where('tbl_master_transaction.t_date >=',date('Y-m-d',strtotime($data['fromdate'])));
	}*/
		if (isset($data['todate']) && !empty($data['todate'])) {
			$this->db->where('tbl_master_transaction.t_date like ', '%' . date('Y-m-d', strtotime($data['todate'])) . '%');
		}
		//$this->db->where('tbl_master_transaction.t_date',date('Y-m-d',time()));
		$this->db->order_by("tbl_master_transaction.id", "desc");
		//$this->db->limit('10', '0');		
		//$this->db->order_by('id', 'desc');
		if (isset($params) && !empty($params)) {
			$this->db->limit($params['limit'], $params['offset']);
		}
		$query = $this->db->get();
		//echo '<pre>';echo $this->db->last_query(); die;
		return $query->result_array();
	}

